static ROOM_GENERATION: AtomicU64 = AtomicU64::new(0);

fn next_generation() -> u64 {
    let mut previous = ROOM_GENERATION.load(Ordering::Relaxed);
    loop {
        let candidate = now_millis().max(previous.saturating_add(1));
        match ROOM_GENERATION.compare_exchange_weak(previous, candidate, Ordering::Relaxed, Ordering::Relaxed) {
            Ok(_) => return candidate,
            Err(actual) => previous = actual,
        }
    }
}
